  id uuid,
  title text,
  description text,
  client_name text,
  client_phone text,
  event_date date,
  event_time time,
  duration_minutes integer,
  meeting_link text,
  color text,
  reminder_2h_sent boolean,
  reminder_30min_sent boolean,
  created_by_user_id uuid,
  created_at timestamptz,
  updated_at timestamptz,
  assigned_closer_id uuid,
  notes text,
  team_id uuid,
  pipeline_client_id uuid,
  meeting_owner_name text,
  clinic_name text,
  scheduled_by text,
  lead_stage text,
  creative_source text,
  title_locked boolean
  )
), ranked_rows as (
  select *,
         row_number() over (
           partition by regexp_replace(coalesce(client_phone, ''), '\\D', '', 'g'), event_date, event_time
           order by updated_at desc nulls last, created_at desc nulls last, id desc
         ) as rn
  from source_rows
)
insert into public.agenda_events (id, title, description, client_name, client_phone, event_date, event_time, duration_minutes, meeting_link, color, reminder_2h_sent, reminder_30min_sent, created_by_user_id, created_at, updated_at, assigned_closer_id, notes, team_id, pipeline_client_id, meeting_owner_name, clinic_name, scheduled_by, lead_stage, creative_source, title_locked)
select id, title, description, client_name, client_phone, event_date, event_time, duration_minutes, meeting_link, color, reminder_2h_sent, reminder_30min_sent, created_by_user_id, created_at, updated_at, assigned_closer_id, notes, team_id, pipeline_client_id, meeting_owner_name, clinic_name, scheduled_by, lead_stage, creative_source, title_locked
from ranked_rows
where rn = 1
on conflict (pipeline_client_id) where pipeline_client_id is not null do update set
  id = excluded.id,
  title = excluded.title,
  description = excluded.description,
  client_name = excluded.client_name,
  client_phone = excluded.client_phone,
  event_date = excluded.event_date,
  event_time = excluded.event_time,
  duration_minutes = excluded.duration_minutes,
  meeting_link = excluded.meeting_link,
  color = excluded.color,
  reminder_2h_sent = excluded.reminder_2h_sent,
